{
  "name": "opencode-readseek",
  "version": "0.13.9",
  "description": "OpenCode plugin for anchored file operations and structural code navigation",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./v2": "./dist/v2.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "readseek",
    "structural-search"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/jarkkojs/readseek.git"
  },
  "license": "Apache-2.0",
  "files": [
    "dist/",
    "README.md"
  ],
  "scripts": {
    "build": "bun build ./index.ts ./v2.ts --outdir dist --target=node --format=esm --packages=external",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit",
    "test": "bun test --conditions=readseek-source --preload ./tests/setup.ts"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "dependencies": {
    "@jarkkojs/readseek": "^0.13.9",
    "@jarkkojs/readseek-api": "^0.13.9",
    "@opencode-ai/plugin": "^1.18.18",
    "diff": "^9.0.0"
  },
  "devDependencies": {
    "@bgotink/kdl": "0.4.0",
    "@opencode/plugin": "^2.0.26",
    "@types/bun": "^1.3.14",
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.26"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  }
}
